import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const ProductPage = () => {
  const { id } = useParams();
  const { addToCart } = useAuth();
  const [selectedImage, setSelectedImage] = useState(0);
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const handleCardClick = () => {
  onNavigate('product', { id: product.id });


  // База данных всех товаров
  const allProducts = {
    1: {
      id: 1,
      name: 'Серьги Лунное сияние',
      price: 12500,
      images: ['/images/луна 1.png', '/images/луна 2.png', '/images/луна 3.png', '/images/луна 4.png'],
      description: 'Элегантные серьги ручной работы из серебра 925 пробы с фианитами. Идеально подходят для вечерних мероприятий и особых случаев.',
      material: 'Серебро 925',
      length: '10 см',
      weight: '8 г',
      category: 'earrings',
      collection: 'luna',
      inStock: true
    },
    2: {
      id: 2,
      name: 'Кольцо Звездная пыль',
      price: 8900,
      images: ['/images/кольцо 1.png', '/images/кольцо 2.png', '/images/кольцо 3.png'],
      description: 'Изящное кольцо с фианитами, которые сверкают как звездная пыль. Комфортно сидит на пальце и подходит для повседневной носки.',
      material: 'Серебро 925',
      size: '17.5',
      weight: '5 г',
      category: 'rings',
      collection: 'solaris',
      inStock: true
    },
    3: {
      id: 3,
      name: 'Колье Солнечная энергия',
      price: 15600,
      images: ['/images/колье 1.png', '/images/колье 2.png'],
      description: 'Роскошное колье с подвеской в виде солнца. Украшено фианитами и создает эффект солнечных лучей.',
      material: 'Серебро 925',
      length: '45 см',
      weight: '12 г',
      category: 'necklaces',
      collection: 'solaris',
      inStock: true
    },
    4: {
      id: 4,
      name: 'Браслет Северное сияние',
      price: 11200,
      images: ['/images/браслет 1.png', '/images/браслет 2.png'],
      description: 'Стильный браслет с гравировкой узоров северного сияния. Регулируемая длина подходит для любого запястья.',
      material: 'Серебро 925',
      length: '19 см',
      weight: '10 г',
      category: 'bracelets',
      collection: 'luna',
      inStock: true
    },
    5: {
      id: 5,
      name: 'Комплект Лунная сказка',
      price: 24500,
      images: ['/images/комплект 1.png', '/images/комплект 2.png'],
      description: 'Полный комплект украшений: серьги, колье и кольцо в едином стиле. Идеально для особых мероприятий.',
      material: 'Серебро 925',
      category: 'sets',
      collection: 'luna',
      inStock: true
    }
  };

  useEffect(() => {
    // Имитация загрузки данных
    const loadProduct = () => {
      setLoading(true);
      setTimeout(() => {
        const productData = allProducts[id] || allProducts[1]; // По умолчанию первый товар
        setProduct(productData);
        setLoading(false);
      }, 500);
    };

    loadProduct();
  }, [id]);

  const handleAddToCart = () => {
    if (product) {
      addToCart(product);
      // Можно добавить уведомление вместо редиректа
      alert('Товар добавлен в корзину!');
    }
  };

  const handleAddToFavorites = () => {
    alert('Товар добавлен в избранное!');
  };

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="animate-pulse">
          <div className="h-4 bg-gray-200 rounded w-1/4 mb-8"></div>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
            <div>
              <div className="h-96 bg-gray-200 rounded-lg mb-4"></div>
              <div className="grid grid-cols-4 gap-2">
                {[...Array(4)].map((_, i) => (
                  <div key={i} className="h-20 bg-gray-200 rounded"></div>
                ))}
              </div>
            </div>
            <div>
              <div className="h-8 bg-gray-200 rounded w-3/4 mb-4"></div>
              <div className="h-6 bg-gray-200 rounded w-1/4 mb-6"></div>
              <div className="space-y-3 mb-6">
                <div className="h-4 bg-gray-200 rounded w-1/2"></div>
                <div className="h-4 bg-gray-200 rounded w-1/3"></div>
              </div>
              <div className="h-12 bg-gray-200 rounded mb-4"></div>
              <div className="h-12 bg-gray-200 rounded"></div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (!product) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-8 text-center">
        <h1 className="text-2xl font-bold text-gray-800 mb-4">Товар не найден</h1>
        <p className="text-gray-600">Извините, запрашиваемый товар не существует.</p>
      </div>
    );
  }

  const getCategoryName = (category) => {
    const categories = {
      rings: 'Кольца',
      earrings: 'Серьги',
      necklaces: 'Колье',
      bracelets: 'Браслеты',
      sets: 'Комплекты'
    };
    return categories[category] || category;
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      {/* Хлебные крошки */}
      <nav className="text-sm text-gray-500 mb-8">
        <a href="#home" className="hover:text-gold-600">Главная</a>
        <span className="mx-2">›</span>
        <a href="#catalog" className="hover:text-gold-600">Каталог</a>
        <span className="mx-2">›</span>
        <span className="capitalize">{getCategoryName(product.category)}</span>
        <span className="mx-2">›</span>
        <span className="text-gray-800 font-medium">{product.name}</span>
      </nav>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
        {/* Изображения */}
        <div>
          <div className="mb-4 bg-gray-50 rounded-lg overflow-hidden">
            <img 
              src={product.images[selectedImage]} 
              alt={product.name}
              className="w-full h-96 object-cover"
            />
          </div>
          <div className="grid grid-cols-4 gap-3">
            {product.images.map((image, index) => (
              <button
                key={index}
                onClick={() => setSelectedImage(index)}
                className={`border-2 rounded-lg overflow-hidden transition-all ${
                  selectedImage === index 
                    ? 'border-gold-600 shadow-md' 
                    : 'border-gray-200 hover:border-gold-400'
                }`}
              >
                <img 
                  src={image} 
                  alt={`${product.name} ${index + 1}`}
                  className="w-full h-20 object-cover"
                />
              </button>
            ))}
          </div>
        </div>

        {/* Информация о товаре */}
        <div>
          <div className="mb-2">
            <span className="inline-block px-3 py-1 bg-blue-100 text-blue-800 rounded-full text-sm font-medium">
              {product.collection === 'luna' ? 'Коллекция LUNA' : 'Коллекция SOLARIS'}
            </span>
          </div>

          <h1 className="text-3xl font-serif font-bold mb-4 text-gray-800">{product.name}</h1>
          <p className="text-2xl text-gold-600 font-bold mb-6">{product.price.toLocaleString()} ₽</p>

          {/* Характеристики */}
          <div className="space-y-3 mb-6">
            <div className="flex items-center">
              <span className="w-6 text-gold-600">●</span>
              <span className="ml-2">Материал: <strong>{product.material}</strong></span>
            </div>
            {product.length && (
              <div className="flex items-center">
                <span className="w-6 text-gold-600">●</span>
                <span className="ml-2">Длина: <strong>{product.length}</strong></span>
              </div>
            )}
            {product.size && (
              <div className="flex items-center">
                <span className="w-6 text-gold-600">●</span>
                <span className="ml-2">Размер: <strong>{product.size}</strong></span>
              </div>
            )}
            {product.weight && (
              <div className="flex items-center">
                <span className="w-6 text-gold-600">●</span>
                <span className="ml-2">Вес: <strong>{product.weight}</strong></span>
              </div>
            )}
            <div className="flex items-center">
              <span className="w-6 text-gold-600">●</span>
              <span className="ml-2">
                Наличие: 
                <strong className={product.inStock ? 'text-green-600 ml-1' : 'text-red-600 ml-1'}>
                  {product.inStock ? 'В наличии' : 'Нет в наличии'}
                </strong>
              </span>
            </div>
          </div>

          {/* Кнопки действий */}
          <div className="space-y-4 mb-8">
            <button
              onClick={handleAddToCart}
              disabled={!product.inStock}
              className={`w-full py-4 rounded-lg font-semibold text-lg transition-all ${
                product.inStock
                  ? 'bg-gold-600 hover:bg-gold-700 text-white shadow-lg hover:shadow-xl'
                  : 'bg-gray-300 text-gray-500 cursor-not-allowed'
              }`}
            >
              {product.inStock ? 'ДОБАВИТЬ В КОРЗИНУ' : 'НЕТ В НАЛИЧИИ'}
            </button>

            <button
              onClick={handleAddToFavorites}
              className="w-full border-2 border-gold-600 text-gold-600 hover:bg-gold-50 py-4 rounded-lg font-semibold flex items-center justify-center gap-2 transition-colors"
            >
              <span>❤️</span>
              ДОБАВИТЬ В ИЗБРАННОЕ
            </button>
          </div>

          {/* Описание */}
          <div className="mt-8">
            <h3 className="text-xl font-semibold mb-4 text-gray-800">📖 Описание</h3>
            <p className="text-gray-600 leading-relaxed text-lg">{product.description}</p>
          </div>

          {/* Дополнительная информация */}
          <div className="mt-8 p-6 bg-gray-50 rounded-lg">
            <h4 className="font-semibold mb-3 text-gray-800">ℹ️ Дополнительная информация</h4>
            <ul className="text-sm text-gray-600 space-y-2">
              <li>• Бесплатная доставка при заказе от 10 000 ₽</li>
              <li>• Гарантия качества 1 год</li>
              <li>• Возврат в течение 14 дней</li>
              <li>• Подарочная упаковка включена</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};
};

export default ProductPage;
